import React, { useEffect, useState } from "react";
import { Link } from "gatsby";

import { BUSINESS, SERVICES, servicePath } from "../content/site";
import { Arrow } from "./LeadForm";

const PhoneIcon = () => (
  <svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true">
    <path
      d="M6.6 3.5 9.4 3l1.8 4.3-2 1.6a12 12 0 0 0 5.9 5.9l1.6-2 4.3 1.8-.5 2.8c-.2 1-1 1.6-2 1.6C10.8 19 5 13.2 5 5.5c0-1 .6-1.8 1.6-2Z"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.6"
    />
  </svg>
);

function Header({ ctaHref }: { ctaHref: string }) {
  const [menuOpen, setMenuOpen] = useState(false);
  const closeMenu = () => setMenuOpen(false);

  useEffect(() => {
    document.documentElement.classList.toggle("menu-open", menuOpen);
    return () => document.documentElement.classList.remove("menu-open");
  }, [menuOpen]);

  return (
    <header className="site-header">
      <a className="skip-link" href="#main">
        Skip to content
      </a>
      <div className="wrap site-header__row">
        <Link to="/" className="site-header__logo" onClick={closeMenu}>
          <img src="/logo-header.svg" alt="Magic House LLC" width={232} height={46} />
        </Link>

        <nav className="site-nav" aria-label="Main">
          <Link to="/about/" activeClassName="is-current">
            About
          </Link>
          <div className="site-nav__group">
            <button type="button" aria-haspopup="true">
              Services
              <svg viewBox="0 0 10 6" width="10" height="6" aria-hidden="true">
                <path d="M1 1l4 4 4-4" fill="none" stroke="currentColor" strokeWidth="1.5" />
              </svg>
            </button>
            <ul className="site-nav__menu">
              {SERVICES.map((service) => (
                <li key={service.slug}>
                  <Link to={servicePath(service)}>{service.name}</Link>
                </li>
              ))}
            </ul>
          </div>
          <Link to="/#portfolio">Our Work</Link>
          <Link to="/contact/" activeClassName="is-current">
            Contact
          </Link>
        </nav>

        <div className="site-header__actions">
          <a className="site-header__phone" href={BUSINESS.phoneHref}>
            <PhoneIcon />
            {BUSINESS.phone}
          </a>
          <a className="btn btn--primary btn--small" href={ctaHref}>
            Schedule a Consultation
          </a>
          <button
            type="button"
            className="site-header__toggle"
            aria-expanded={menuOpen}
            aria-controls="mobile-menu"
            aria-label={menuOpen ? "Close menu" : "Open menu"}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span />
            <span />
          </button>
        </div>
      </div>

      <nav id="mobile-menu" className={`mobile-menu${menuOpen ? " is-open" : ""}`} aria-label="Mobile">
        <Link to="/" onClick={closeMenu}>
          Home
        </Link>
        <Link to="/about/" onClick={closeMenu}>
          About
        </Link>
        <p className="mobile-menu__label">Services</p>
        {SERVICES.map((service) => (
          <Link key={service.slug} className="mobile-menu__sub" to={servicePath(service)} onClick={closeMenu}>
            {service.name}
          </Link>
        ))}
        <Link to="/#portfolio" onClick={closeMenu}>
          Our Work
        </Link>
        <Link to="/contact/" onClick={closeMenu}>
          Contact
        </Link>
      </nav>
    </header>
  );
}

function Footer() {
  return (
    <footer className="site-footer">
      <div className="wrap site-footer__grid">
        <div className="site-footer__brand">
          <img src="/logo.svg" alt="Magic House LLC" width={300} height={83} loading="lazy" />
          <p>{BUSINESS.pillars.join("  |  ")}</p>
        </div>

        <div>
          <h2>Services</h2>
          <ul>
            {SERVICES.map((service) => (
              <li key={service.slug}>
                <Link to={servicePath(service)}>{service.name}</Link>
              </li>
            ))}
          </ul>
        </div>

        <div>
          <h2>Company</h2>
          <ul>
            <li>
              <Link to="/about/">About</Link>
            </li>
            <li>
              <Link to="/#portfolio">Our Work</Link>
            </li>
            <li>
              <Link to="/contact/">Contact</Link>
            </li>
          </ul>
        </div>

        <div>
          <h2>Get In Touch</h2>
          <ul>
            <li>
              <a href={BUSINESS.phoneHref}>{BUSINESS.phone}</a>
            </li>
            <li>
              <a href={`mailto:${BUSINESS.email}`}>{BUSINESS.email}</a>
            </li>
            <li>{BUSINESS.cities.join(", ")}</li>
          </ul>
        </div>
      </div>

      <div className="wrap site-footer__legal">
        <p>© {new Date().getFullYear()} Magic House LLC. All rights reserved.</p>
        <Link to="/privacy/">Privacy Policy</Link>
      </div>
    </footer>
  );
}

/** Thumb-reach actions on phones, where the header's phone number and button are hidden. */
function MobileBar({ ctaHref }: { ctaHref: string }) {
  return (
    <div className="mobile-bar">
      <a href={BUSINESS.phoneHref}>
        <PhoneIcon />
        Call Now
      </a>
      <a href={ctaHref}>
        Schedule
        <Arrow />
      </a>
    </div>
  );
}

function useReveal() {
  useEffect(() => {
    const targets = document.querySelectorAll<HTMLElement>("[data-reveal]");
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add("is-visible");
            observer.unobserve(entry.target);
          }
        });
      },
      { rootMargin: "0px 0px -8% 0px" }
    );
    targets.forEach((target) => observer.observe(target));
    return () => observer.disconnect();
  }, []);
}

type LayoutProps = {
  children: React.ReactNode;
  /** Pages without the closing contact section send visitors to /contact/ instead. */
  ctaHref?: string;
};

export function Layout({ children, ctaHref = "#consultation" }: LayoutProps) {
  useReveal();

  return (
    <>
      <Header ctaHref={ctaHref} />
      <main id="main">{children}</main>
      <Footer />
      <MobileBar ctaHref={ctaHref} />
    </>
  );
}
