import React, { useEffect, useRef, useState } from "react";

type Props = {
  name: string;
  alt: string;
  /** Off shows the still poster, so a row of clips doesn't compete for attention. */
  active?: boolean;
};

type NetworkInfo = { connection?: { saveData?: boolean; effectiveType?: string } };

/**
 * A silent looping clip. The poster paints immediately; the video only downloads
 * once it is on screen, and pauses when it leaves. Reduced-motion, data-saver,
 * and slow-connection visitors keep the poster.
 */
export function VideoLoop({ name, alt, active = true }: Props) {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [playing, setPlaying] = useState(false);

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;

    if (!active) {
      video.pause();
      setPlaying(false);
      return;
    }

    const connection = (navigator as Navigator & NetworkInfo).connection;
    const slowNetwork = connection?.saveData || /2g|3g/.test(connection?.effectiveType ?? "");
    if (slowNetwork || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;

    // React doesn't reliably set this attribute, and autoplay needs it.
    video.muted = true;

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          if (!video.getAttribute("src")) video.src = `/videos/${name}.mp4`;
          video.play().catch(() => undefined);
        } else {
          video.pause();
        }
      },
      { threshold: 0.2 }
    );

    observer.observe(video);
    return () => observer.disconnect();
  }, [name, active]);

  return (
    <div className={`video-loop${playing ? " is-playing" : ""}`}>
      <img
        src={`/videos/${name}.webp`}
        alt={alt}
        width={720}
        height={1280}
        loading="lazy"
        decoding="async"
      />
      <video
        ref={videoRef}
        loop
        muted
        playsInline
        preload="none"
        aria-hidden="true"
        tabIndex={-1}
        onPlaying={() => setPlaying(true)}
      />
    </div>
  );
}
