    <div className="actions">
      <a className={`btn ${dark ? "btn--light" : "btn--primary"}`} href="#consultation">
        Schedule a Consultation
        <Arrow />
      </a>
      <a className={`btn ${dark ? "btn--ghost-light" : "btn--ghost"}`} href={BUSINESS.phoneHref}>
        Call {BUSINESS.phone}
      </a>
    </div>
