/**
 * Three projects on show, one in focus. Only the center clip plays: a row of
 * moving videos gives the eye nowhere to rest.
 */
export function WorkReel() {
  const [active, setActive] = useState(0);
  const pointerStart = useRef<number | null>(null);
  const count = PROJECTS.length;
  const move = (step: number) => setActive((current) => (current + step + count) % count);

  return (
    <section className="section section--dark work" id="portfolio">
      <div className="wrap">
        <div className="work__head" data-reveal>
          <div>
            <p className="eyebrow">Our Work</p>
            <h2>Recent Projects</h2>
          </div>
          <p>Every project tells a story. Here are some of the spaces we've had the honor of transforming.</p>
        </div>

        <div
          className="reel"
          role="group"
          aria-roledescription="carousel"
          aria-label="Recent projects"
          onKeyDown={(event) => {
            if (event.key === "ArrowLeft") move(-1);
            if (event.key === "ArrowRight") move(1);
          }}
          onPointerDown={(event) => {
            pointerStart.current = event.clientX;
          }}
          onPointerUp={(event) => {
            const distance = event.clientX - (pointerStart.current ?? event.clientX);
            pointerStart.current = null;
            if (Math.abs(distance) > 40) move(distance < 0 ? 1 : -1);
          }}
        >
          <ul className="reel__stage">
            {PROJECTS.map((project, index) => {
              // -1 is left, 0 is center, 1 is right. Anything further waits out of sight.
              const position = ((index - active + count + 1) % count) - 1;
              const state = position === 0 ? " is-active" : Math.abs(position) > 1 ? " is-away" : "";

              return (
                <li
                  key={project.video}
                  className={`reel__slide${state}`}
                  style={{ "--position": position } as React.CSSProperties}
                >
                  <figure>
                    <VideoLoop
                      name={project.video}
                      alt={`${project.title}: ${project.detail}`}
                      active={position === 0}
                    />
                    <figcaption>
                      <strong>{project.title}</strong>
                      <span>{project.detail}</span>
                      <span className="work__place">Treasure Valley</span>
                    </figcaption>
                  </figure>
                  {position !== 0 && (
                    <button
                      type="button"
                      className="reel__pick"
                      aria-label={`Show ${project.title}`}
                      onClick={() => setActive(index)}
                    />
                  )}
                </li>
              );
            })}
          </ul>

          <div className="reel__controls">
            <button type="button" className="reel__prev" aria-label="Previous project" onClick={() => move(-1)}>
              <Arrow />
            </button>
            <p aria-live="polite">
              Project {active + 1} of {count}
            </p>
            <button type="button" aria-label="Next project" onClick={() => move(1)}>
              <Arrow />
            </button>
          </div>
        </div>
      </div>
    </section>
  );
}

