/**
 * The closing section on every page. Its roofline echoes the peak in the logo.
 * The form comes before the details in the markup so phones reach it sooner.
 */
export function ContactSection({
  eyebrow = "Get In Touch",
  title = "Let's Build Your Next Chapter",
  body = "Whether you're buying, remodeling, preparing to sell, or improving your investment, Magic House manages the entire process, from strategy to execution.",
  project,
}: {
  eyebrow?: string;
  title?: string;
  body?: string;
  project?: string;
}) {
  return (
    <section className="contact" id="consultation">
      <svg className="contact__roof" viewBox="0 0 1440 120" preserveAspectRatio="none" aria-hidden="true">
        <polygon className="contact__roof-sky" points="0,0 720,0 720,3 0,120" />
        <polygon className="contact__roof-sky" points="1440,0 720,0 720,3 1440,120" />
        <polyline className="contact__roof-line" points="0,120 720,3 1440,120" />
      </svg>
      <div className="wrap contact__grid" id="contact">
        <div className="contact__copy" data-reveal>
          <p className="eyebrow">{eyebrow}</p>
          <h2>{title}</h2>
          <p className="contact__body">{body}</p>
          <p className="contact__promise">One call. One team. Start to finish.</p>
        </div>
        <LeadForm project={project} />
        <ContactDetails />
      </div>
    </section>
  );
}
