import React from "react";

import { BUSINESS, SITE_URL } from "../content/site";

type Crumb = { name: string; path: string };

type Props = {
  title: string;
  description: string;
  path: string;
  crumbs?: Crumb[];
  schema?: object[];
};

const BUSINESS_SCHEMA = {
  "@context": "https://schema.org",
  "@type": "HomeAndConstructionBusiness",
  "@id": `${SITE_URL}/#business`,
  name: BUSINESS.name,
  slogan: BUSINESS.tagline,
  description: "Family-owned design, investment, remodel, and consulting company in the Treasure Valley, Idaho.",
  url: `${SITE_URL}/`,
  logo: `${SITE_URL}/logo.svg`,
  image: `${SITE_URL}/og-image.jpg`,
  telephone: "+1-986-283-4379",
  email: BUSINESS.email,
  founder: { "@type": "Person", name: BUSINESS.founder },
  address: { "@type": "PostalAddress", addressRegion: "ID", addressCountry: "US" },
  areaServed: BUSINESS.cities.map((city) => ({ "@type": "City", name: `${city}, ID` })),
  openingHoursSpecification: {
    "@type": "OpeningHoursSpecification",
    dayOfWeek: ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday"],
    opens: "08:00",
    closes: "19:00",
  },
};

const jsonLd = (data: object) => (
  <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(data) }} />
);

export function Seo({ title, description, path, crumbs, schema = [] }: Props) {
  const url = `${SITE_URL}${path}`;
  const image = `${SITE_URL}/og-image.jpg`;

  return (
    <>
      <title>{title}</title>
      <meta name="description" content={description} />
      <link rel="canonical" href={url} />
      <meta name="theme-color" content="#383D42" />
      <link rel="icon" href="/favicon.svg" type="image/svg+xml" />
      <link rel="icon" href="/favicon-32.png" sizes="32x32" type="image/png" />
      <link rel="apple-touch-icon" href="/apple-touch-icon.png" />

      <meta property="og:type" content="website" />
      <meta property="og:site_name" content={BUSINESS.name} />
      <meta property="og:title" content={title} />
      <meta property="og:description" content={description} />
      <meta property="og:url" content={url} />
      <meta property="og:image" content={image} />
      <meta name="twitter:card" content="summary_large_image" />
      <meta name="twitter:title" content={title} />
      <meta name="twitter:description" content={description} />
      <meta name="twitter:image" content={image} />

      {jsonLd(BUSINESS_SCHEMA)}
      {crumbs &&
        jsonLd({
          "@context": "https://schema.org",
          "@type": "BreadcrumbList",
          itemListElement: crumbs.map((crumb, index) => ({
            "@type": "ListItem",
            position: index + 1,
            name: crumb.name,
            item: `${SITE_URL}${crumb.path}`,
          })),
        })}
      {schema.map((entry, index) => (
        <React.Fragment key={index}>{jsonLd(entry)}</React.Fragment>
      ))}
    </>
  );
}

/** Structured data for a service page: breadcrumbs come from Seo's `crumbs`. */
export const serviceSchema = (name: string, description: string) => ({
  "@context": "https://schema.org",
  "@type": "Service",
  name,
  description,
  serviceType: name,
  provider: { "@id": `${SITE_URL}/#business` },
  areaServed: BUSINESS.cities.map((city) => `${city}, ID`),
});
